function draw(){const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;ctx.clearRect(0,0,w,h);let cols=12,rows=9,tw=w/cols,th=h/rows;const a=areas[state.area];
// Island canvas with tile-based terrain and softly rounded water
ctx.fillStyle=a.water;ctx.fillRect(0,0,w,h);for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){let edge=Math.min(x,cols-1-x,y,rows-1-y), v=hash(x+state.area*17,y);let land=(edge>0||((x>1&&x<10)&&(y>1&&y<7)))&& !(edge===0&&v>.25);let px=x*tw,py=y*th;if(land){ctx.fillStyle=(x===0||y===0||x===cols-1||y===rows-1)?a.sand:(v>.83?'#9ac37b':a.color);ctx.fillRect(px,py,tw+1,th+1);if(v>.87){ctx.fillStyle='#ffffff18';ctx.fillRect(px+tw*.2,py+th*.2,tw*.25,2)}}}
// sandy edge & winding path
ctx.strokeStyle=a.path;ctx.lineWidth=Math.max(9,tw*.44);ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(tw*2,th*7.3);ctx.bezierCurveTo(tw*3,th*6.4,tw*4,th*6.8,tw*5,th*5.7);ctx.bezierCurveTo(tw*6.2,th*4.5,tw*7.3,th*5.1,tw*7,th*3.4);ctx.bezierCurveTo(tw*6.8,th*2.5,tw*8,th*2.1,tw*9.5,th*2.7);ctx.stroke();
